{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The mapmaker receives a plea for help.",
      "visual_description": "Mara the Cartographer stands at a ruined city gate, clutching a torn map while the Oracle Lamp flickers beside her.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "The glass diver is summoned through a mirror.",
      "visual_description": "A cracked mirror in an abandoned guardhouse ripples and Glass Diver steps out, helmet gleaming with reflected torchlight.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of cursed towers.",
      "visual_description": "Inside a crumbling courtyard, the Oracle Lamp's single eye glows red as it casts a shadow of a distant spire.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "They encounter the sleeping tax collector at a checkpoint.",
      "visual_description": "A desk cluttered with stamped papers blocks a stone archway; the Sleeping Tax Collector snores on a ledger book pillow.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The tin fox scouts ahead through rubble.",
      "visual_description": "The Tin Fox scurries over broken cobblestones, key-wind tail ticking, blue eyes scanning a collapsed archway.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "A magic door refuses to open without a riddle.",
      "visual_description": "A massive bronze door inscribed with glowing runes blocks a corridor; the Oracle Lamp's flame dims in warning.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The glass diver swims through a window to bypass the door.",
      "visual_description": "Glass Diver presses a hand against a barred window, which ripples like water as he begins to pass through.",
      "characters": ["glass_diver", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "Mara reads a secret path on her map.",
      "visual_description": "Mara unrolls a stained map, pointing to a dashed line while the Tin Fox watches from her shoulder.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The armored patrol passes nearby.",
      "visual_description": "Through a gap in a broken wall, three armored figures march in unison, their helmets hiding their faces.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "They hide behind old royal banners.",
      "visual_description": "A vast hall hung with faded banners of gold and blue; the party crouches behind a fallen tapestry as footsteps echo.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp reveals a trap in the floor.",
      "visual_description": "The Oracle Lamp shines its light onto a flagstone that tilts slightly, revealing a pit of spikes below.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The sleeping tax collector wakes briefly to stamp a permission slip.",
      "visual_description": "Sleeping Tax Collector stirs, mechanically stamps a blank paper, then slumps back onto the ledger pillow.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "They climb a cursed tower to get a vantage point.",
      "visual_description": "A spiral staircase winds upward; the walls pulse with faint, sickly green light as the Glass Diver leads.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The tin fox spots the escape bridge from the tower top.",
      "visual_description": "From a broken parapet, the Tin Fox points a metal paw at a distant bridge spanning a chasm, its blue eyes reflecting the sky.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "They descend and face a locked grate.",
      "visual_description": "A rusted iron grate blocks the path to the bridge; the Oracle Lamp's flame sputters as if in frustration.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The glass diver opens the grate by melting the lock with reflected sunlight.",
      "visual_description": "Glass Diver angles his helmet to focus a beam of light onto the lock, which glows red and drips molten metal.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the crumbling bridge.",
      "visual_description": "The party sprints across a stone bridge missing several planks, the Tin Fox leaping from gap to gap, the Oracle Lamp bobbing wildly.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "They reach safety as the bridge collapses behind them.",
      "visual_description": "The group stands on solid ground, watching the bridge crumble into the ravine; the Oracle Lamp's flame steadies to a calm glow.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

